function dspError(statusCode, code, reasons) {
    return {
        statusCode: statusCode,
        headers: { 'Content-Type': 'application/json' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': reasons }
    };
}

const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
if (!body.providerBaseUrl || !body.assetId || !body.agreementId) {
    return [dspError(422, 'invalid_request', ['providerBaseUrl, assetId, and agreementId are required']), null];
}

const providerBaseUrl = body.providerBaseUrl.replace(/\/$/, '');
msg._dspConsumer = {
    providerBaseUrl: providerBaseUrl,
    assetId: body.assetId,
    agreementId: body.agreementId,
    windowFrom: body.windowFrom || '',
    windowTo: body.windowTo || ''
};
msg.url = providerBaseUrl + '/dsp/transfers';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    agreementId: body.agreementId,
    assetId: body.assetId,
    format: 'http-pull',
    parameters: { windowFrom: msg._dspConsumer.windowFrom, windowTo: msg._dspConsumer.windowTo }
};
return [null, msg];

function dspError(statusCode, code, reasons) {
    return {
        statusCode: statusCode,
        headers: { 'Content-Type': 'application/json' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': reasons }
    };
}

const ok = msg.statusCode === 202 && msg.payload && typeof msg.payload === 'object' && typeof msg.payload.transferId === 'string';
if (!ok) {
    return [dspError(502, 'provider_transfer_create_failed', ['provider did not return a valid transferId', 'statusCode=' + msg.statusCode, 'payload=' + JSON.stringify(msg.payload)]), null];
}

msg._dspConsumer.transferId = msg.payload.transferId;
msg.url = msg._dspConsumer.providerBaseUrl + '/dsp/transfers/' + encodeURIComponent(msg.payload.transferId);
msg.method = 'GET';
msg.payload = '';
return [null, msg];

function dspError(statusCode, code, reasons) {
    return {
        statusCode: statusCode,
        headers: { 'Content-Type': 'application/json' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': reasons }
    };
}

const transfer = msg.payload;
if (!transfer || typeof transfer !== 'object' || transfer.state !== 'COMPLETED') {
    return [dspError(502, 'provider_transfer_not_completed', ['transfer did not reach COMPLETED', 'state=' + (transfer && transfer.state)]), null];
}
if (transfer.format !== 'http-pull' || !transfer.access || !transfer.access.url) {
    return [dspError(502, 'provider_access_object_missing', ['transfer has no http-pull access.url', 'format=' + transfer.format]), null];
}

msg.url = transfer.access.url;
msg.method = 'GET';
msg.payload = '';
return [null, msg];

function dspError(statusCode, code, reasons) {
    return {
        statusCode: statusCode,
        headers: { 'Content-Type': 'application/json' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': reasons }
    };
}

const data = msg.payload;
if (!data || typeof data !== 'object' || !Array.isArray(data.rows)) {
    return [dspError(502, 'provider_data_pull_failed', ['data endpoint did not return {rows: [...]}', 'statusCode=' + msg.statusCode]), null, null];
}

const rows = data.rows;
const respMsg = {
    statusCode: 202,
    headers: { 'Content-Type': 'application/json' },
    payload: { status: 'accepted', transferId: msg._dspConsumer.transferId, assetId: msg._dspConsumer.assetId, rowCount: rows.length }
};
if (rows.length === 0) {
    return [null, respMsg, null];
}
const fanoutMsg = {
    payload: rows,
    ingest_timestamp: new Date().toISOString(),
    source_topic: msg._dspConsumer.providerBaseUrl + '/api/data/' + msg._dspConsumer.assetId,
    _dsp_assetId: msg._dspConsumer.assetId
};
return [null, respMsg, fanoutMsg];

const row = msg.payload;
const envelope = {
    ingest_timestamp: msg.ingest_timestamp,
    source_topic: msg.source_topic,
    kafka_partition: 0,
    kafka_offset: 0,
    kafka_key: msg._dsp_assetId,
    raw_payload: JSON.stringify(row)
};

const m = global.get('metrics') || {};
m.facis_dsp_ingest_records_published_total = (m.facis_dsp_ingest_records_published_total || 0) + 1;
global.set('metrics', m);

return {
    topic: env.get('DSP_INGEST_TOPIC') || 'dsp.ingest.raw',
    key: msg._dsp_assetId,
    payload: JSON.stringify(envelope)
};
